// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Liquid".
*/

let theShader, dpr = window.devicePixelRatio, ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2455372/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T ((3600.+time)*.8)
#define S smoothstep
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define MN min(R.x,R.y)
#define lum(a) vec3(dot(vec3(.21,.71,.07),a))
#define hue(a) (.25+.6*cos(3.14*clamp(a,2.8,3.6)+vec3(0,83,21)))
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
float rnd(vec2 a) {
	vec3 p=fract(vec3(a.xyx)*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p) {
	float t=.0, a=1.; mat2 m=mat2(1.2,-.8,.8,1.2);
	for (float i=.0; i<6.; i++) {
		t+=a*noise(p);
		p=2.*p*m;
		a*=.5;
	}
	return t;
}
vec2 smin(vec2 a, vec2 b, float k) {
	vec2 h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
// A little critter. If you want to see more of these,
// go to https://codepen.io/atzedent/pen/wvOrYMj
float logo(vec2 uv) {
	vec3 col=vec3(0);
	uv*=5.;
	vec2 p=vec2(sin(T+uv.y), cos(T+uv.x))*.75;
	return 1.-SE(cos(1.9-sin(length(p)/(.55+length(uv)))),.1);
}
float placeLogo() {
	vec2 p=FC/R;
	p*=vec2(R.x/R.y,1);
	p-=vec2(R.x/R.y,0);
	p+=vec2(.08,-.075);
	return logo(p*12.);
}
void main() {
	vec2 uv=(FC-.5*R)/MN, p=(FC/MN);
	vec3 col=vec3(0);
	// move and squish the domain
	p+=vec2(2.75,-2.75);
	p*=rot(-1.5707*2.5);
	p=smin(p,-uv,1.5);
	p*=rot(.39);
	p.x+=.8;
	p*=.5;
	// warp the domain multiple times to generate
	// the wavy noise pattern
	// see: https://iquilezles.org/articles/warp/
	float k=fbm(p*noise(uv*.2*fbm(p-T*.2)+T*.02)+.125*fbm(T*.01-p*2.+.5*fbm(T*.03-p*3.+.5*fbm(p*6.-T*.2))));
	// colorize noise
	vec3 d=mix(vec3(0),hue(2.8+k),k);
	col+=lum(d)*.8+d*.8;
	col/=1.+exp(-col*col*col);
	col=pow(col,vec3(.4545));
	// vignette
	p=(FC-.5*R)/R;
	col=mix(vec3(0,.05,.2),col,pow(S(.45,.0,dot(p*p,p*p)),12.));
	// raise darkest value to dark gray
	col=max(col,.1);
	// add little animation to the lower right corner
	col=max(col,vec3(.1,.2,.4)*placeLogo());
	O=vec4(col,1);
}

